 v_items jsonb := p_journey->'items';
 v_groups jsonb := p_journey->'groups';
 v_item jsonb;
 v_member text;
BEGIN
 FOREACH v_member IN ARRAY ARRAY['member-2','member-3','member-4','member-5'] LOOP
  IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p_journey->'members') m WHERE m->>'id'=v_member) THEN
   RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='london_members_missing';
  END IF;
 END LOOP;
 FOR v_item IN SELECT value FROM jsonb_array_elements(v_seed) LOOP
  IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(v_items) i WHERE i->>'id'=v_item->>'id') THEN
   v_items:=v_items || jsonb_build_array(jsonb_set(v_item,'{tripId}',p_journey->'tripId',true));
  END IF;
 END LOOP;
 IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(v_groups) g WHERE g->>'id'='london-early') THEN
  v_groups:=v_groups || jsonb_build_array(jsonb_build_object('id','london-early','tripId',p_journey->'tripId','name','倫敦前段','memberIds',jsonb_build_array('member-2','member-3','member-4','member-5'),'membershipConfirmed',true));
 END IF;
 RETURN jsonb_set(jsonb_set(p_journey,'{items}',v_items),'{groups}',v_groups);
END;
$fn$;
CREATE FUNCTION public.tripbook_add_london_prelude(p_trip_id uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $fn$
DECLARE
 v_old jsonb;
 v_next jsonb;
BEGIN
 IF auth.uid() IS NULL OR NOT public.tripbook_can_edit(p_trip_id) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='journey_editor_required'; END IF;
 SELECT journey INTO v_old FROM public.tripbook_journeys WHERE trip_id=p_trip_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='journey_not_found'; END IF;
 v_next:=public.tripbook_with_london(v_old);
 PERFORM public.tripbook_validate_journey(v_next-'memos',p_trip_id::text,true);
 IF v_next IS DISTINCT FROM v_old THEN
  UPDATE public.tripbook_journeys SET journey=v_next,revision=revision+1,updated_at=clock_timestamp(),updated_by=auth.uid() WHERE trip_id=p_trip_id;
 END IF;
 RETURN public.tripbook_journey_envelope(p_trip_id);
END;
$fn$;
REVOKE ALL ON FUNCTION public.tripbook_with_london(jsonb) FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.tripbook_add_london_prelude(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.tripbook_add_london_prelude(uuid) TO authenticated;
COMMIT;
